  ) u_wdata (
    .clk_i   (clk_i    ),
    .rst_ni  (rst_ni  ),

    // from register interface
    .we     (wdata_we),
    .wd     (wdata_wd),

    // from internal hardware
    .de     (1'b0),
    .d      ('0  ),

    // to internal hardware
    .qe     (),
    .q      (reg2hw.wdata.q ),

    // to register interface (read)
    .qs     (wdata_qs)
  );


  // R[rdata]: V(True)

  prim_subreg_ext #(
    .DW    (32)
  ) u_rdata (
    .re     (rdata_re),
    .we     (1'b0),
    .wd     ('0),
    .d      (hw2reg.rdata.d),
    .qre    (),
    .qe     (),
    .q      (),
    .qs     (rdata_qs)
  );


  // R[transaction_valid]: V(False)

  prim_subreg #(
    .DW      (1),
    .SWACCESS("RW"),
    .RESVAL  (1'h0)
  ) u_transaction_valid (
    .clk_i   (clk_i    ),
    .rst_ni  (rst_ni  ),

    // from register interface
    .we     (transaction_valid_we),
    .wd     (transaction_valid_wd),

    // from internal hardware
    .de     (1'b0),
    .d      ('0  ),

    // to internal hardware
    .qe     (reg2hw.transaction_valid.qe),
    .q      (reg2hw.transaction_valid.q ),

    // to register interface (read)
    .qs     (transaction_valid_qs)
  );


  // R[status]: V(True)

  //   F[busy]: 0:0
  prim_subreg_ext #(
    .DW    (1)
  ) u_status_busy (
    .re     (status_busy_re),
    .we     (1'b0),
    .wd     ('0),
    .d      (hw2reg.status.busy.d),
    .qre    (),
    .qe     (),
    .q      (),
    .qs     (status_busy_qs)
  );


  //   F[done]: 1:1
  prim_subreg_ext #(
    .DW    (1)
  ) u_status_done (
    .re     (status_done_re),
    .we     (1'b0),
    .wd     ('0),
    .d      (hw2reg.status.done.d),
    .qre    (),
    .qe     (),
    .q      (),
    .qs     (status_done_qs)
  );


  //   F[error]: 2:2
  prim_subreg_ext #(
    .DW    (1)
  ) u_status_error (
    .re     (status_error_re),
    .we     (1'b0),
    .wd     ('0),
    .d      (hw2reg.status.error.d),
    .qre    (),
    .qe     (),
    .q      (),
    .qs     (status_error_qs)
  );




  logic [19:0] addr_hit;
  always_comb begin
    addr_hit = '0;
    addr_hit[ 0] = (reg_addr == MEM_CTRL_CG_RST_OFFSET);
    addr_hit[ 1] = (reg_addr == MEM_CTRL_TIMING_CFG_OFFSET);
    addr_hit[ 2] = (reg_addr == MEM_CTRL_CLK_DIV_OFFSET);
    addr_hit[ 3] = (reg_addr == MEM_CTRL_MBA0_OFFSET);
    addr_hit[ 4] = (reg_addr == MEM_CTRL_MBA1_OFFSET);
    addr_hit[ 5] = (reg_addr == MEM_CTRL_DEVICE_OFFSET);
    addr_hit[ 6] = (reg_addr == MEM_CTRL_RAM_OPT_OFFSET);
    addr_hit[ 7] = (reg_addr == MEM_CTRL_IRQ_EN_OFFSET);
    addr_hit[ 8] = (reg_addr == MEM_CTRL_BURST_CFG_OFFSET);
    addr_hit[ 9] = (reg_addr == MEM_CTRL_PROTOCOL_OFFSET);
    addr_hit[10] = (reg_addr == MEM_CTRL_TRANSACTION_TYPE_OFFSET);
    addr_hit[11] = (reg_addr == MEM_CTRL_RESPONSE_TYPE_OFFSET);
    addr_hit[12] = (reg_addr == MEM_CTRL_DATA_SIZE_OFFSET);
    addr_hit[13] = (reg_addr == MEM_CTRL_EXTERNAL_ADDRESS_OFFSET);
    addr_hit[14] = (reg_addr == MEM_CTRL_INTERNAL_ADDRESS_OFFSET);
    addr_hit[15] = (reg_addr == MEM_CTRL_TRANS_AUTO_OFFSET);
    addr_hit[16] = (reg_addr == MEM_CTRL_WDATA_OFFSET);
    addr_hit[17] = (reg_addr == MEM_CTRL_RDATA_OFFSET);
    addr_hit[18] = (reg_addr == MEM_CTRL_TRANSACTION_VALID_OFFSET);
    addr_hit[19] = (reg_addr == MEM_CTRL_STATUS_OFFSET);
  end

  assign addrmiss = (reg_re || reg_we) ? ~|addr_hit : 1'b0 ;

  // Check sub-word write is permitted
  always_comb begin
    wr_err = (reg_we &
              ((addr_hit[ 0] & (|(MEM_CTRL_PERMIT[ 0] & ~reg_be))) |
               (addr_hit[ 1] & (|(MEM_CTRL_PERMIT[ 1] & ~reg_be))) |
               (addr_hit[ 2] & (|(MEM_CTRL_PERMIT[ 2] & ~reg_be))) |
               (addr_hit[ 3] & (|(MEM_CTRL_PERMIT[ 3] & ~reg_be))) |
               (addr_hit[ 4] & (|(MEM_CTRL_PERMIT[ 4] & ~reg_be))) |
               (addr_hit[ 5] & (|(MEM_CTRL_PERMIT[ 5] & ~reg_be))) |
               (addr_hit[ 6] & (|(MEM_CTRL_PERMIT[ 6] & ~reg_be))) |
               (addr_hit[ 7] & (|(MEM_CTRL_PERMIT[ 7] & ~reg_be))) |
               (addr_hit[ 8] & (|(MEM_CTRL_PERMIT[ 8] & ~reg_be))) |
               (addr_hit[ 9] & (|(MEM_CTRL_PERMIT[ 9] & ~reg_be))) |
               (addr_hit[10] & (|(MEM_CTRL_PERMIT[10] & ~reg_be))) |
               (addr_hit[11] & (|(MEM_CTRL_PERMIT[11] & ~reg_be))) |
               (addr_hit[12] & (|(MEM_CTRL_PERMIT[12] & ~reg_be))) |
               (addr_hit[13] & (|(MEM_CTRL_PERMIT[13] & ~reg_be))) |
               (addr_hit[14] & (|(MEM_CTRL_PERMIT[14] & ~reg_be))) |
               (addr_hit[15] & (|(MEM_CTRL_PERMIT[15] & ~reg_be))) |
               (addr_hit[16] & (|(MEM_CTRL_PERMIT[16] & ~reg_be))) |
               (addr_hit[17] & (|(MEM_CTRL_PERMIT[17] & ~reg_be))) |
               (addr_hit[18] & (|(MEM_CTRL_PERMIT[18] & ~reg_be))) |
               (addr_hit[19] & (|(MEM_CTRL_PERMIT[19] & ~reg_be)))));
  end

  assign cg_rst_clock_gate_en_we = addr_hit[0] & reg_we & !reg_error;
  assign cg_rst_clock_gate_en_wd = reg_wdata[0];

  assign cg_rst_rst_n_we = addr_hit[0] & reg_we & !reg_error;
  assign cg_rst_rst_n_wd = reg_wdata[1];

  assign timing_cfg_latency_access_we = addr_hit[1] & reg_we & !reg_error;
  assign timing_cfg_latency_access_wd = reg_wdata[9:0];

  assign timing_cfg_read_write_recovery_we = addr_hit[1] & reg_we & !reg_error;
  assign timing_cfg_read_write_recovery_wd = reg_wdata[13:10];

  assign timing_cfg_rwds_delay_line_we = addr_hit[1] & reg_we & !reg_error;
  assign timing_cfg_rwds_delay_line_wd = reg_wdata[16:14];

  assign timing_cfg_additional_latency_autocheck_en_we = addr_hit[1] & reg_we & !reg_error;
  assign timing_cfg_additional_latency_autocheck_en_wd = reg_wdata[17];

  assign timing_cfg_cs_max_we = addr_hit[1] & reg_we & !reg_error;
  assign timing_cfg_cs_max_wd = reg_wdata[31:18];

  assign clk_div_we = addr_hit[2] & reg_we & !reg_error;
  assign clk_div_wd = reg_wdata[7:0];

  assign mba0_we = addr_hit[3] & reg_we & !reg_error;
  assign mba0_wd = reg_wdata[31:0];

  assign mba1_we = addr_hit[4] & reg_we & !reg_error;
  assign mba1_wd = reg_wdata[31:0];

  assign device_device_we = addr_hit[5] & reg_we & !reg_error;
  assign device_device_wd = reg_wdata[0];

  assign device_dt0_we = addr_hit[5] & reg_we & !reg_error;
  assign device_dt0_wd = reg_wdata[1];

  assign device_dt1_we = addr_hit[5] & reg_we & !reg_error;
  assign device_dt1_wd = reg_wdata[2];

  assign device_sdio_en_we = addr_hit[5] & reg_we & !reg_error;
  assign device_sdio_en_wd = reg_wdata[3];

  assign ram_opt_cross_boundary_en_we = addr_hit[6] & reg_we & !reg_error;
  assign ram_opt_cross_boundary_en_wd = reg_wdata[0];

  assign ram_opt_opt_read_enable_we = addr_hit[6] & reg_we & !reg_error;
  assign ram_opt_opt_read_enable_wd = reg_wdata[2:1];

  assign irq_en_we = addr_hit[7] & reg_we & !reg_error;
  assign irq_en_wd = reg_wdata[0];

  assign burst_cfg_cs_auto_burst_enable_we = addr_hit[8] & reg_we & !reg_error;
  assign burst_cfg_cs_auto_burst_enable_wd = reg_wdata[1:0];

  assign burst_cfg_cs_maximum_check_enable_we = addr_hit[8] & reg_we & !reg_error;
  assign burst_cfg_cs_maximum_check_enable_wd = reg_wdata[3:2];

  assign protocol_we = addr_hit[9] & reg_we & !reg_error;
  assign protocol_wd = reg_wdata[1:0];

  assign transaction_type_we = addr_hit[10] & reg_we & !reg_error;
  assign transaction_type_wd = reg_wdata[2:0];

  assign response_type_we = addr_hit[11] & reg_we & !reg_error;
  assign response_type_wd = reg_wdata[3:0];

  assign data_size_we = addr_hit[12] & reg_we & !reg_error;
  assign data_size_wd = reg_wdata[9:0];

  assign external_address_we = addr_hit[13] & reg_we & !reg_error;
  assign external_address_wd = reg_wdata[31:0];

  assign internal_address_we = addr_hit[14] & reg_we & !reg_error;
  assign internal_address_wd = reg_wdata[31:0];

  assign trans_auto_we = addr_hit[15] & reg_we & !reg_error;
  assign trans_auto_wd = reg_wdata[0];

  assign wdata_we = addr_hit[16] & reg_we & !reg_error;
  assign wdata_wd = reg_wdata[31:0];

  assign rdata_re = addr_hit[17] & reg_re & !reg_error;

  assign transaction_valid_we = addr_hit[18] & reg_we & !reg_error;
  assign transaction_valid_wd = reg_wdata[0];

  assign status_busy_re = addr_hit[19] & reg_re & !reg_error;

  assign status_done_re = addr_hit[19] & reg_re & !reg_error;

  assign status_error_re = addr_hit[19] & reg_re & !reg_error;

  // Read data return
  always_comb begin
    reg_rdata_next = '0;
    unique case (1'b1)
      addr_hit[0]: begin
        reg_rdata_next[0] = cg_rst_clock_gate_en_qs;
        reg_rdata_next[1] = cg_rst_rst_n_qs;
      end

      addr_hit[1]: begin
        reg_rdata_next[9:0] = timing_cfg_latency_access_qs;
        reg_rdata_next[13:10] = timing_cfg_read_write_recovery_qs;
        reg_rdata_next[16:14] = timing_cfg_rwds_delay_line_qs;
        reg_rdata_next[17] = timing_cfg_additional_latency_autocheck_en_qs;
        reg_rdata_next[31:18] = timing_cfg_cs_max_qs;
      end

      addr_hit[2]: begin
        reg_rdata_next[7:0] = clk_div_qs;
      end

      addr_hit[3]: begin
        reg_rdata_next[31:0] = mba0_qs;
      end

      addr_hit[4]: begin
        reg_rdata_next[31:0] = mba1_qs;
      end

      addr_hit[5]: begin
        reg_rdata_next[0] = device_device_qs;
        reg_rdata_next[1] = device_dt0_qs;
        reg_rdata_next[2] = device_dt1_qs;
        reg_rdata_next[3] = device_sdio_en_qs;
      end

      addr_hit[6]: begin
        reg_rdata_next[0] = ram_opt_cross_boundary_en_qs;
        reg_rdata_next[2:1] = ram_opt_opt_read_enable_qs;
      end

      addr_hit[7]: begin
        reg_rdata_next[0] = irq_en_qs;
      end

      addr_hit[8]: begin
        reg_rdata_next[1:0] = burst_cfg_cs_auto_burst_enable_qs;
        reg_rdata_next[3:2] = burst_cfg_cs_maximum_check_enable_qs;
      end

      addr_hit[9]: begin
        reg_rdata_next[1:0] = protocol_qs;
      end

      addr_hit[10]: begin
        reg_rdata_next[2:0] = transaction_type_qs;
      end

      addr_hit[11]: begin
        reg_rdata_next[3:0] = response_type_qs;
      end

      addr_hit[12]: begin
        reg_rdata_next[9:0] = data_size_qs;
      end

      addr_hit[13]: begin
        reg_rdata_next[31:0] = external_address_qs;
      end

      addr_hit[14]: begin
        reg_rdata_next[31:0] = internal_address_qs;
      end

      addr_hit[15]: begin
        reg_rdata_next[0] = trans_auto_qs;
      end

      addr_hit[16]: begin
        reg_rdata_next[31:0] = wdata_qs;
      end

      addr_hit[17]: begin
        reg_rdata_next[31:0] = rdata_qs;
      end

      addr_hit[18]: begin
        reg_rdata_next[0] = transaction_valid_qs;
      end

      addr_hit[19]: begin
        reg_rdata_next[0] = status_busy_qs;
        reg_rdata_next[1] = status_done_qs;
        reg_rdata_next[2] = status_error_qs;
      end

      default: begin
        reg_rdata_next = '1;
      end
    endcase
  end

  // Unused signal tieoff

  // wdata / byte enable are not always fully used
  // add a blanket unused statement to handle lint waivers
  logic unused_wdata;
  logic unused_be;
  assign unused_wdata = ^reg_wdata;
  assign unused_be = ^reg_be;

  // Assertions for Register Interface
  `ASSERT(en2addrHit, (reg_we || reg_re) |-> $onehot0(addr_hit))

endmodule

module mem_ctrl_reg_top_intf
#(
  parameter int AW = 7,
  localparam int DW = 32
) (
  input logic clk_i,
  input logic rst_ni,
  REG_BUS.in  regbus_slave,
  // To HW
  output mem_ctrl_reg_pkg::mem_ctrl_reg2hw_t reg2hw, // Write
  input  mem_ctrl_reg_pkg::mem_ctrl_hw2reg_t hw2reg, // Read
  // Config
  input devmode_i // If 1, explicit error return for unmapped register access
);
 localparam int unsigned STRB_WIDTH = DW/8;

`include "register_interface/typedef.svh"
`include "register_interface/assign.svh"

  // Define structs for reg_bus
  typedef logic [AW-1:0] addr_t;
  typedef logic [DW-1:0] data_t;
  typedef logic [STRB_WIDTH-1:0] strb_t;
  `REG_BUS_TYPEDEF_ALL(reg_bus, addr_t, data_t, strb_t)

  reg_bus_req_t s_reg_req;
  reg_bus_rsp_t s_reg_rsp;
  
  // Assign SV interface to structs
  `REG_BUS_ASSIGN_TO_REQ(s_reg_req, regbus_slave)
  `REG_BUS_ASSIGN_FROM_RSP(regbus_slave, s_reg_rsp)

  

  mem_ctrl_reg_top #(
    .reg_req_t(reg_bus_req_t),
    .reg_rsp_t(reg_bus_rsp_t),
    .AW(AW)
  ) i_regs (
    .clk_i,
    .rst_ni,
    .reg_req_i(s_reg_req),
    .reg_rsp_o(s_reg_rsp),
    .reg2hw, // Write
    .hw2reg, // Read
    .devmode_i
  );
  
endmodule


